<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>One-time credentials</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body>
@include('core._shell-start')<main class="ad-page ac-page"><header class="ad-page-head"><div><p class="ad-eyebrow">{{ $context === 'reset' ? 'Password reset' : 'Account created' }}</p><h1>Give these details to {{ $user->name }}</h1><p>This is the only time the temporary password is shown.</p></div></header>
<section class="ad-cred" id="credential-panel"><div class="ad-cred-head"><div><h2>Sign-in details</h2><p class="ad-meta">They must choose a new password at the next sign-in.</p></div><span class="ad-once">Shown once</span></div>
<dl class="ac-credentials"><div><dt>Name</dt><dd>{{ $user->name }}</dd></div><div><dt>Role</dt><dd>{{ $user->roles->pluck('name')->join(', ') }}</dd></div><div><dt>Username</dt><dd>{{ $user->username }}</dd></div><div><dt>Temporary password</dt><dd><code id="temporary-password">{{ $temporary_password }}</code></dd></div></dl>
<div class="ad-actions ac-no-print"><button class="oak-btn oak-btn-quiet" type="button" data-copy-password>Copy password</button><button class="oak-btn oak-btn-quiet" type="button" onclick="window.print()">Print slip</button></div></section>
<label class="ac-noted ac-no-print"><input type="checkbox" data-noted> I have noted or printed these details</label><a class="oak-btn oak-btn-primary ac-no-print" data-done aria-disabled="true" href="{{ route('staff.access.index') }}">Done</a></main>@include('core._shell-end') @livewireScripts
<script>const noted=document.querySelector('[data-noted]'),done=document.querySelector('[data-done]'),password=document.getElementById('temporary-password');noted.addEventListener('change',()=>{done.setAttribute('aria-disabled',String(!noted.checked));done.classList.toggle('is-disabled',!noted.checked)});done.addEventListener('click',e=>{e.preventDefault();if(!noted.checked)return;password.textContent='';window.location.replace(done.href)});document.querySelector('[data-copy-password]').addEventListener('click',async e=>{await navigator.clipboard.writeText(password.textContent);e.currentTarget.textContent='Copied'});window.addEventListener('pagehide',()=>{password.textContent=''});done.classList.add('is-disabled');</script></body></html>
